CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(display_name) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY own_profile_name ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_aviv_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id, left(coalesce(NEW.raw_user_meta_data->>'full_name',''),100)); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.create_aviv_profile() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER aviv_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_aviv_profile();
INSERT INTO public.profiles(id) SELECT id FROM auth.users ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.user_id=_user_id AND r.role=_role AND p.active) $$;
ALTER TABLE public.services ADD COLUMN full_description text NOT NULL DEFAULT '', ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.pages ADD COLUMN seo_title text NOT NULL DEFAULT '', ADD COLUMN seo_description text NOT NULL DEFAULT '', ADD COLUMN content jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.faqs ADD COLUMN category text NOT NULL DEFAULT 'General', ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.public_settings ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE public.media_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), storage_path text NOT NULL UNIQUE, alt_text text NOT NULL DEFAULT '', caption text NOT NULL DEFAULT '', mime_type text NOT NULL, file_size integer NOT NULL CHECK(file_size>0 AND file_size<=5242880), published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.media_assets TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.media_assets TO authenticated; GRANT ALL ON public.media_assets TO service_role;
ALTER TABLE public.media_assets ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_media ON public.media_assets FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY admin_media ON public.media_assets FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.bookings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_reference text NOT NULL UNIQUE, client_name text NOT NULL, client_email text NOT NULL, client_phone text, service_id uuid NOT NULL REFERENCES public.services(id) ON DELETE RESTRICT, price_minor bigint NOT NULL CHECK(price_minor>=0), currency text NOT NULL DEFAULT 'NGN' CHECK(currency='NGN'), requested_start timestamptz, alternative_start timestamptz, confirmed_start timestamptz, confirmed_end timestamptz, time_zone text NOT NULL DEFAULT 'Africa/Lagos', payment_status text NOT NULL DEFAULT 'pending' CHECK(payment_status IN ('pending','successful','failed','refunded')), booking_status text NOT NULL DEFAULT 'pending' CHECK(booking_status IN ('pending','confirmed','cancelled','completed','reschedule_requested')), payment_reference text UNIQUE, confirmed_at timestamptz, cancellation_status text, refund_status text, meeting_provider text, daily_room_id text, meeting_link_issued_at timestamptz, session_status text NOT NULL DEFAULT 'not_started' CHECK(session_status IN ('not_started','ready','in_progress','ended')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(confirmed_end IS NULL OR confirmed_start IS NOT NULL AND confirmed_end>confirmed_start));
GRANT SELECT ON public.bookings TO authenticated; GRANT ALL ON public.bookings TO service_role;
ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_booking_read ON public.bookings FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE INDEX bookings_created_idx ON public.bookings(created_at DESC); CREATE INDEX bookings_service_idx ON public.bookings(service_id);
CREATE TABLE public.payment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.bookings(id) ON DELETE RESTRICT, paystack_reference text NOT NULL, event_type text NOT NULL, processing_status text NOT NULL DEFAULT 'received' CHECK(processing_status IN ('received','processed','failed')), idempotency_key text NOT NULL UNIQUE, verification_metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.payment_events TO authenticated; GRANT ALL ON public.payment_events TO service_role;
ALTER TABLE public.payment_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_payment_read ON public.payment_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX payment_success_once ON public.payment_events(paystack_reference) WHERE event_type='charge.success'; CREATE INDEX payment_booking_idx ON public.payment_events(booking_id);
CREATE TABLE public.booking_access_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.bookings(id) ON DELETE RESTRICT, token_hash text NOT NULL UNIQUE CHECK(length(token_hash)=64), purpose text NOT NULL CHECK(purpose IN ('manage','session')), expires_at timestamptz NOT NULL, redeemed_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.booking_access_tokens TO service_role; ALTER TABLE public.booking_access_tokens ENABLE ROW LEVEL SECURITY;
CREATE INDEX booking_token_booking_idx ON public.booking_access_tokens(booking_id);
CREATE TABLE public.contact_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, subject text NOT NULL, message text NOT NULL CHECK(length(message)<=2000), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','read','closed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.contact_submissions TO authenticated; GRANT ALL ON public.contact_submissions TO service_role;
ALTER TABLE public.contact_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_contact_read ON public.contact_submissions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_contact_update ON public.contact_submissions FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, resource_type text NOT NULL, resource_id text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_audit_read ON public.audit_logs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE INDEX audit_created_idx ON public.audit_logs(created_at DESC);
CREATE FUNCTION public.aviv_touch_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.updated_at=now(); INSERT INTO public.audit_logs(actor_id,action,resource_type,resource_id) VALUES(auth.uid(),TG_OP,TG_TABLE_NAME,coalesce(to_jsonb(NEW)->>'id',to_jsonb(NEW)->>'key')); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.aviv_touch_audit() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER service_audit BEFORE INSERT OR UPDATE ON public.services FOR EACH ROW EXECUTE FUNCTION public.aviv_touch_audit();
CREATE TRIGGER page_audit BEFORE INSERT OR UPDATE ON public.pages FOR EACH ROW EXECUTE FUNCTION public.aviv_touch_audit();
CREATE TRIGGER faq_audit BEFORE INSERT OR UPDATE ON public.faqs FOR EACH ROW EXECUTE FUNCTION public.aviv_touch_audit();
CREATE TRIGGER setting_audit BEFORE INSERT OR UPDATE ON public.public_settings FOR EACH ROW EXECUTE FUNCTION public.aviv_touch_audit();
CREATE TRIGGER media_audit BEFORE INSERT OR UPDATE ON public.media_assets FOR EACH ROW EXECUTE FUNCTION public.aviv_touch_audit();
CREATE FUNCTION public.aviv_booking_integrity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.price_minor<>OLD.price_minor OR NEW.currency<>OLD.currency OR NEW.service_id<>OLD.service_id) THEN RAISE EXCEPTION 'Booking price snapshot is immutable'; END IF; IF NEW.time_zone<>'Africa/Lagos' AND NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=NEW.time_zone) THEN RAISE EXCEPTION 'Invalid time zone'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.aviv_booking_integrity() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER booking_integrity BEFORE INSERT OR UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION public.aviv_booking_integrity();
CREATE POLICY aviv_storage_admin ON storage.objects FOR ALL TO authenticated USING(bucket_id='aviv-media' AND public.has_role(auth.uid(),'admin')) WITH CHECK(bucket_id='aviv-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY aviv_storage_public ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='aviv-media' AND EXISTS(SELECT 1 FROM public.media_assets m WHERE m.storage_path=name AND m.published));